import 'server-only';
import bundledExtract from '../../data/climate-history/era5-annual-2016-2025.json' with { type: 'json' };

/**
 * Reader for the reviewed 77-province annual ERA5 extract.
 *
 * The bundle is generated by `scripts/build_era5_annual_extract.py` from one
 * 10-year (2016-2025) daily ERA5 request per province centroid. Only annual
 * aggregates travel in the bundle; each province record carries the request
 * URL, retrieval time, provider grid cell, daily row count and the SHA-256 of
 * the canonical daily payload it was reduced from. The reader re-validates the
 * whole structure and fails closed: one inconsistent row rejects the bundle
 * instead of serving a number nobody can trace.
 */

export const ANNUAL_EXTRACT_SCHEMA = 'tadih-era5-annual-extract-v1';
export const ANNUAL_EXTRACT_FIRST_YEAR = 2016;
export const ANNUAL_EXTRACT_LAST_YEAR = 2025;

const ARCHIVE_URL = 'https://archive-api.open-meteo.com/v1/archive';
const SHA256_PATTERN = /^[0-9a-f]{64}$/;
const PROVINCE_CODE_PATTERN = /^\d{2}$/;

export type AnnualYearStats = {
  year: number;
  tmeanC: number | null;
  tmaxMeanC: number | null;
  tminMeanC: number | null;
  hotDays38C: number | null;
  rainfallTotalMm: number | null;
  longestDrySpellDays: number | null;
  drySpellEvents5d: number | null;
  calendarDays: number;
  daysWithData: {
    temperatureMean: number;
    temperatureMax: number;
    temperatureMin: number;
    precipitation: number;
  };
  completeYear: boolean;
};

export type AnnualProvinceRecord = {
  provinceCode: string;
  nameEn: string;
  region: string;
  requestedLatitude: number;
  requestedLongitude: number;
  providerGridLatitude: number;
  providerGridLongitude: number;
  providerElevationM: number | null;
  requestUrl: string;
  retrievedAt: string;
  dailySha256: string;
  dailyRows: number;
  firstDay: string;
  lastDay: string;
  years: AnnualYearStats[];
};

export type AnnualExtractEnvelope = {
  schema: string;
  sourceId: string;
  providerModel: string;
  dataKind: string;
  spatialSupport: string;
  licence: string;
  attribution: string;
  attributionUrl: string;
  timezone: string;
  firstYear: number;
  lastYear: number;
  generatedAt: string;
  dailySha256Basis: string;
  provinces: Record<string, AnnualProvinceRecord>;
};

export type AnnualExtractRead =
  | { status: 'ok'; province: AnnualProvinceRecord; years: AnnualYearStats[]; missingYears: number[] }
  | { status: 'unknown_province' }
  | { status: 'invalid'; reason: string };

export type AnnualExtractValidation =
  | { ok: true; extract: AnnualExtractEnvelope }
  | { ok: false; reason: string };

class AnnualExtractError extends Error {}

function fail(reason: string): never {
  throw new AnnualExtractError(reason);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value);
}

function numberOrNull(value: unknown, label: string): number | null {
  if (value === null || value === undefined) return null;
  if (!isFiniteNumber(value)) fail(`${label} ไม่ใช่ตัวเลขหรือ null`);
  return value;
}

function integerInRangeOrNull(value: unknown, low: number, high: number, label: string): number | null {
  if (value === null || value === undefined) return null;
  if (!isInteger(value) || value < low || value > high) fail(`${label} อยู่นอกช่วงที่ถูกต้อง`);
  return value;
}

function parseTimestamp(value: unknown, label: string): string {
  if (typeof value !== 'string' || !value || !Number.isFinite(Date.parse(value))) {
    fail(`${label} ไม่ใช่วันเวลาที่อ่านได้`);
  }
  return value;
}

function calendarDays(year: number): number {
  return Math.round((Date.UTC(year + 1, 0, 1) - Date.UTC(year, 0, 1)) / 86_400_000);
}

function parseYearRow(raw: unknown, firstYear: number, lastYear: number, province: string): AnnualYearStats {
  if (!isRecord(raw)) fail(`จังหวัด ${province}: แถวรายปีไม่ใช่ object`);
  const year = raw.year;
  if (!isInteger(year) || year < firstYear || year > lastYear) {
    fail(`จังหวัด ${province}: ปี ${String(year)} อยู่นอกช่วง`);
  }
  const days = calendarDays(year);
  if (raw.calendar_days !== days) {
    fail(`จังหวัด ${province} ปี ${year}: calendar_days ไม่ตรงกับปฏิทิน`);
  }
  const tmeanC = numberOrNull(raw.tmean_c, `จังหวัด ${province} ปี ${year}: tmean_c`);
  const tmaxMeanC = numberOrNull(raw.tmax_mean_c, `จังหวัด ${province} ปี ${year}: tmax_mean_c`);
  const tminMeanC = numberOrNull(raw.tmin_mean_c, `จังหวัด ${province} ปี ${year}: tmin_mean_c`);
  const rainfallTotalMm = numberOrNull(raw.rainfall_total_mm, `จังหวัด ${province} ปี ${year}: rainfall_total_mm`);
  if (rainfallTotalMm !== null && rainfallTotalMm < 0) {
    fail(`จังหวัด ${province} ปี ${year}: rainfall_total_mm ติดลบ`);
  }
  const hotDays38C = integerInRangeOrNull(raw.hot_days_38c, 0, days, `จังหวัด ${province} ปี ${year}: hot_days_38c`);
  const longestDrySpellDays = integerInRangeOrNull(raw.longest_dry_spell_days, 0, days, `จังหวัด ${province} ปี ${year}: longest_dry_spell_days`);
  const drySpellEvents5d = integerInRangeOrNull(raw.dry_spell_events_5d, 0, days, `จังหวัด ${province} ปี ${year}: dry_spell_events_5d`);
  const counts = raw.days_with_data;
  if (!isRecord(counts)) fail(`จังหวัด ${province} ปี ${year}: ขาด days_with_data`);
  const temperatureMean = integerInRangeOrNull(counts.temperature_mean, 0, days, `จังหวัด ${province} ปี ${year}: days_with_data.temperature_mean`);
  const temperatureMax = integerInRangeOrNull(counts.temperature_max, 0, days, `จังหวัด ${province} ปี ${year}: days_with_data.temperature_max`);
  const temperatureMin = integerInRangeOrNull(counts.temperature_min, 0, days, `จังหวัด ${province} ปี ${year}: days_with_data.temperature_min`);
  const precipitation = integerInRangeOrNull(counts.precipitation, 0, days, `จังหวัด ${province} ปี ${year}: days_with_data.precipitation`);
  if (temperatureMean === null || temperatureMax === null || temperatureMin === null || precipitation === null) {
    fail(`จังหวัด ${province} ปี ${year}: days_with_data ต้องเป็นจำนวนเต็ม`);
  }
  if (raw.complete_year !== true && raw.complete_year !== false) {
    fail(`จังหวัด ${province} ปี ${year}: complete_year ต้องเป็น boolean`);
  }
  if (raw.complete_year && (temperatureMax !== days || precipitation !== days)) {
    fail(`จังหวัด ${province} ปี ${year}: complete_year=true แต่ข้อมูลไม่ครบปฏิทิน`);
  }
  if (
    tminMeanC !== null && tmeanC !== null && tmaxMeanC !== null
    && !(tminMeanC <= tmeanC && tmeanC <= tmaxMeanC)
  ) {
    fail(`จังหวัด ${province} ปี ${year}: ค่าต่ำสุด/เฉลี่ย/สูงสุดเรียงผิด`);
  }
  return {
    year,
    tmeanC,
    tmaxMeanC,
    tminMeanC,
    hotDays38C,
    rainfallTotalMm,
    longestDrySpellDays,
    drySpellEvents5d,
    calendarDays: days,
    daysWithData: { temperatureMean, temperatureMax, temperatureMin, precipitation },
    completeYear: raw.complete_year,
  };
}

function parseProvince(raw: unknown, code: string, firstYear: number, lastYear: number): AnnualProvinceRecord {
  if (!isRecord(raw)) fail(`จังหวัด ${code}: record ไม่ใช่ object`);
  const coordinate = (key: string, low: number, high: number) => {
    const value = raw[key];
    if (!isFiniteNumber(value) || value < low || value > high) fail(`จังหวัด ${code}: ${key} ไม่ถูกต้อง`);
    return value;
  };
  const requestedLatitude = coordinate('requested_latitude', -90, 90);
  const requestedLongitude = coordinate('requested_longitude', -180, 180);
  const providerGridLatitude = coordinate('provider_grid_latitude', -90, 90);
  const providerGridLongitude = coordinate('provider_grid_longitude', -180, 180);
  const providerElevationM = raw.provider_elevation_m === null || raw.provider_elevation_m === undefined
    ? null
    : numberOrNull(raw.provider_elevation_m, `จังหวัด ${code}: provider_elevation_m`);
  const requestUrl = raw.request_url;
  if (typeof requestUrl !== 'string' || !requestUrl.startsWith(ARCHIVE_URL)) {
    fail(`จังหวัด ${code}: request_url ไม่ใช่ ERA5 archive endpoint`);
  }
  if (!requestUrl.includes(`${firstYear}-01-01`) || !requestUrl.includes(`${lastYear}-12-31`)) {
    fail(`จังหวัด ${code}: request_url ไม่ตรงกับช่วงปีของ extract`);
  }
  const retrievedAt = parseTimestamp(raw.retrieved_at, `จังหวัด ${code} retrieved_at`);
  const dailySha256 = raw.daily_sha256;
  if (typeof dailySha256 !== 'string' || !SHA256_PATTERN.test(dailySha256)) {
    fail(`จังหวัด ${code}: daily_sha256 ต้องเป็น hex 64 ตัว`);
  }
  const dailyRows = raw.daily_rows;
  if (!isInteger(dailyRows) || dailyRows < 1 || dailyRows > 4000) {
    fail(`จังหวัด ${code}: daily_rows อยู่นอกช่วง`);
  }
  if (raw.first_day !== `${firstYear}-01-01` || raw.last_day !== `${lastYear}-12-31`) {
    fail(`จังหวัด ${code}: first_day/last_day ไม่ตรงกับช่วงปี`);
  }
  const yearsRaw = raw.years;
  if (!Array.isArray(yearsRaw) || yearsRaw.length === 0) fail(`จังหวัด ${code}: years ว่าง`);
  const seen = new Set<number>();
  const years: AnnualYearStats[] = [];
  for (const row of yearsRaw) {
    const parsed = parseYearRow(row, firstYear, lastYear, code);
    if (seen.has(parsed.year)) fail(`จังหวัด ${code}: ปี ${parsed.year} ซ้ำ`);
    seen.add(parsed.year);
    years.push(parsed);
  }
  years.sort((a, b) => a.year - b.year);
  return {
    provinceCode: code,
    nameEn: typeof raw.name_en === 'string' ? raw.name_en : '',
    region: typeof raw.region === 'string' ? raw.region : '',
    requestedLatitude,
    requestedLongitude,
    providerGridLatitude,
    providerGridLongitude,
    providerElevationM,
    requestUrl,
    retrievedAt,
    dailySha256,
    dailyRows,
    firstDay: raw.first_day as string,
    lastDay: raw.last_day as string,
    years,
  };
}

function parseExtract(value: unknown): AnnualExtractEnvelope {
  if (!isRecord(value)) fail('extract ต้องเป็น JSON object');
  if (value.schema !== ANNUAL_EXTRACT_SCHEMA) fail('schema ไม่ตรงกับสัญญา annual extract');
  if (value.source_id !== 'open_meteo' || value.provider_model !== 'era5') {
    fail('source_id/provider_model ไม่ใช่ open_meteo era5');
  }
  if (value.data_kind !== 'estimated' || value.spatial_support !== 'grid_point') {
    fail('data_kind/spatial_support ไม่ตรงกับสัญญา');
  }
  if (value.licence !== 'CC-BY-4.0') fail('licence ไม่ใช่ CC-BY-4.0');
  if (typeof value.attribution !== 'string' || !value.attribution) fail('attribution ว่าง');
  if (typeof value.attribution_url !== 'string' || !value.attribution_url.startsWith('https://open-meteo.com')) {
    fail('attribution_url ไม่ใช่ open-meteo.com');
  }
  if (value.timezone !== 'Asia/Bangkok') fail('timezone ไม่ใช่ Asia/Bangkok');
  if (!isInteger(value.first_year) || !isInteger(value.last_year) || value.first_year > value.last_year) {
    fail('first_year/last_year ไม่ถูกต้อง');
  }
  const firstYear = value.first_year;
  const lastYear = value.last_year;
  const generatedAt = parseTimestamp(value.generated_at, 'generated_at');
  if (typeof value.daily_sha256_basis !== 'string' || !value.daily_sha256_basis) {
    fail('daily_sha256_basis ว่าง');
  }
  const provincesRaw = value.provinces;
  if (!isRecord(provincesRaw) || Object.keys(provincesRaw).length === 0) {
    fail('provinces ว่างหรือไม่ใช่ object');
  }
  const provinces: Record<string, AnnualProvinceRecord> = {};
  for (const [code, record] of Object.entries(provincesRaw)) {
    if (!PROVINCE_CODE_PATTERN.test(code)) fail(`รหัสจังหวัด ${code} ไม่ใช่ 2 หลัก`);
    provinces[code] = parseProvince(record, code, firstYear, lastYear);
  }
  return {
    schema: ANNUAL_EXTRACT_SCHEMA,
    sourceId: 'open_meteo',
    providerModel: 'era5',
    dataKind: 'estimated',
    spatialSupport: 'grid_point',
    licence: 'CC-BY-4.0',
    attribution: value.attribution,
    attributionUrl: value.attribution_url,
    timezone: 'Asia/Bangkok',
    firstYear,
    lastYear,
    generatedAt,
    dailySha256Basis: value.daily_sha256_basis,
    provinces,
  };
}

export function validateAnnualExtract(value: unknown): AnnualExtractValidation {
  try {
    return { ok: true, extract: parseExtract(value) };
  } catch (error) {
    if (error instanceof AnnualExtractError) return { ok: false, reason: error.message };
    throw error;
  }
}

// Validated once per process: the bundle is static and ~200 KB, so re-parsing it
// on every request would burn Worker CPU for no benefit.
const BUNDLED_VALIDATION = validateAnnualExtract(bundledExtract);

export function readReviewedAnnualExtract(
  provinceCode: string,
  startYear: number,
  endYear: number,
  options: { extract?: unknown } = {},
): AnnualExtractRead {
  const validation = options.extract === undefined
    ? BUNDLED_VALIDATION
    : validateAnnualExtract(options.extract);
  if (!validation.ok) return { status: 'invalid', reason: validation.reason };
  const { extract } = validation;
  const province = extract.provinces[provinceCode];
  if (!province) return { status: 'unknown_province' };
  const years = province.years.filter((row) => row.year >= startYear && row.year <= endYear);
  const present = new Set(province.years.map((row) => row.year));
  // A window with no overlapping year is "no coverage here", not "all years missing";
  // only a partial overlap can honestly name the years that are absent.
  const missingYears: number[] = [];
  if (years.length > 0) {
    for (let year = startYear; year <= endYear; year += 1) {
      if (!present.has(year)) missingYears.push(year);
    }
  }
  return { status: 'ok', province, years, missingYears };
}
